      <path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" />
    </svg>
  );
}

function ConfirmDeleteDialog({ open, onCancel, onConfirm, image, returnFocusRef }) {
  const dialogRef = useRef(null);
  const cancelBtnRef = useRef(null);
  const titleId = useId();
  const descId = useId();

  // Focus management: move focus into dialog on open, restore on close
  useEffect(() => {
    if (!open) return;
    const previouslyFocused = document.activeElement;
    // Focus the safer "Cancel" button by default
    requestAnimationFrame(() => {
      cancelBtnRef.current && cancelBtnRef.current.focus();
    });
    return () => {
      const target = (returnFocusRef && returnFocusRef.current) || previouslyFocused;
      if (target && typeof target.focus === "function") target.focus();
    };
  }, [open, returnFocusRef]);

  // Lock body scroll while open
  useEffect(() => {
    if (!open) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { document.body.style.overflow = prev; };
  }, [open]);

