    const root = dialogRef.current;
    if (!root) return;
    const focusables = root.querySelectorAll(
      'a[href], button:not([disabled]), textarea, input, select, [tabindex]:not([tabindex="-1"])'
    );
    if (focusables.length === 0) return;
    const first = focusables[0];
    const last = focusables[focusables.length - 1];
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  }, [onCancel]);

  if (!open) return null;

  return (
    <div className="modal-backdrop" onMouseDown={(e) => {
      // Click on backdrop (not the dialog) closes
      if (e.target === e.currentTarget) onCancel();
    }}>
      <div
        ref={dialogRef}
        className="modal"
        role="alertdialog"
        aria-modal="true"
        aria-labelledby={titleId}
        aria-describedby={descId}
        onKeyDown={onKeyDown}
      >
        <div className="modal-header">
          <div className="modal-icon" aria-hidden="true"><AlertIcon /></div>
          <h2 className="modal-title" id={titleId}>Delete this image?</h2>
        </div>
        <div className="modal-body" id={descId}>
          <p>
            <strong>{image.title}</strong> will be permanently removed from your library.
          </p>
          <p>This action cannot be undone.</p>
        </div>
        <div className="modal-footer">
          <button
            type="button"
            ref={cancelBtnRef}
            className="btn btn-secondary"
            onClick={onCancel}
          >
            Cancel
          </button>
          <button
            type="button"
            className="btn btn-danger btn-solid"
            onClick={onConfirm}
          >
            <TrashIcon />
            Delete image
          </button>
        </div>
      </div>
    </div>
  );
}

function ImagePreview() {
  const [open, setOpen] = useState(false);
  const [status, setStatus] = useState("");
  const [deleted, setDeleted] = useState(false);
  const triggerRef = useRef(null);

  const openDialog = () => setOpen(true);
  const closeDialog = () => setOpen(false);
  const confirmDelete = () => {
    setOpen(false);
    setDeleted(true);
    setStatus(`${IMAGE.title} was deleted from your library.`);
  };

  return (
    <>
      <article className="preview" aria-labelledby="img-title">
        <h1 id="img-title">{IMAGE.title}</h1>
        <p className="meta">
          <span>Photo by {IMAGE.photographer}</span>
          <span className="dot" aria-hidden="true"></span>
          <span>{IMAGE.dims}</span>
          <span className="dot" aria-hidden="true"></span>
          <span>{IMAGE.size}</span>
        </p>
        <figure className="preview-figure">
          {!deleted ? (
            <img src={IMAGE.src} alt={IMAGE.alt} />
          ) : (
            <div style={{
              padding: "4rem 1rem",
              color: "var(--text-muted)",
              textAlign: "center",
            }}>
              Image removed from library.
            </div>
          )}
        </figure>
        <figcaption className="preview-figcaption">{IMAGE.caption}</figcaption>
        <div className="actions">
          <button type="button" className="btn btn-secondary">Download</button>
          <button type="button" className="btn btn-secondary">Share</button>
          <button
            type="button"
            ref={triggerRef}
            className="trigger btn btn-danger"
            onClick={openDialog}
            disabled={deleted}
            aria-haspopup="dialog"
            aria-expanded={open}
          >
            <TrashIcon />
            Delete
          </button>
        </div>
      </article>

      <ConfirmDeleteDialog
        open={open}
        onCancel={closeDialog}
        onConfirm={confirmDelete}
        image={IMAGE}
        returnFocusRef={triggerRef}
      />

      <div className="sr-only" role="status" aria-live="polite">{status}</div>
    </>
  );
}

